(()=>{'use strict';
const $=s=>document.querySelector(s),base='https://api.novaclient.tech/license/account';
let csrf='',currentTitle=null,profileId=null,loading=0;
const labels={playtime:'Time played',tries:'Map attempts',saves:'Saves',freezes:'Freezes',lasts:'Lasts',deaths:'Deaths'};
const paths={playtime:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',tries:'m5 5 14 7-14 7V5Z',saves:'M12 21s-9-5-9-12a5 5 0 0 1 9-3 5 5 0 0 1 9 3c0 7-9 12-9 12Z',freezes:'M12 2v20M3.3 7l17.4 10M3.3 17 20.7 7M8 4l4 3 4-3M8 20l4-3 4 3',lasts:'m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3Z',deaths:'M6 16v-2a7 7 0 1 1 12 0v2h-3v5H9v-5H6Zm3-6h.01M15 10h.01'};
const show=(id,on=true)=>{const el=$(id);if(el)el.hidden=!on},number=n=>new Intl.NumberFormat('en').format(n);
const format=(v,m)=>m==='playtime'?`${number(Math.floor(v/3600))}h ${Math.floor(v%3600/60)}m`:number(v);
const publicId=new URLSearchParams(location.search).get('player'),rankings=location.pathname.replace(/\/$/,'').endsWith('/leaderboards');
function message(t){$('#message').textContent=t||''}
function text(tag,value,cls){const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;return e}
function icon(path){const s=document.createElementNS('http://www.w3.org/2000/svg','svg');s.setAttribute('viewBox','0 0 24 24');s.setAttribute('aria-hidden','true');const p=document.createElementNS(s.namespaceURI,'path');p.setAttribute('d',path);s.append(p);return s}
async function api(path,form){const token=localStorage.getItem('nova-session');const headers={...(token?{Authorization:'Bearer '+token}:{})};if(form)headers['Content-Type']='application/x-www-form-urlencoded';const r=await fetch(base+path,{cache:'no-store',credentials:'omit',headers,...(form?{method:'POST',body:new URLSearchParams({...form,csrf})}:{})});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||'Could not load this page. Try again.'),{status:r.status});return d}
function profile(p,own){profileId=p.id;show('#intro',false);show('#profile');show('#reverify',own);$('#player-name').textContent=p.name;$('#role').textContent=p.role;currentTitle=p.title;NovaTitles.attach($('#title'),p.title);
 let controls=$('#profile-links');if(!controls){controls=text('div','','profile-links');controls.id='profile-links';$('#profile').prepend(controls)}controls.replaceChildren();const back=text('a','Back to leaderboards','quiet');back.href='/leaderboards/';controls.append(back);
 if(p.title){const pause=text('button',NovaTitles.paused?'Play title animation':'Pause title animation','quiet');pause.type='button';pause.onclick=()=>{NovaTitles.pause(!NovaTitles.paused);pause.textContent=NovaTitles.paused?'Play title animation':'Pause title animation'};controls.append(pause)}
 $('#stats').replaceChildren();for(const metric of Object.keys(labels)){const stat=text('a','','stat');stat.href='/leaderboards/?metric='+metric;stat.setAttribute('aria-label','View '+labels[metric]+' leaderboard');stat.append(icon(paths[metric]),text('span',labels[metric]),text('strong',p.stats?format(p.stats[metric],metric):'—'),text('small',p.rankings?.[metric]?'#'+number(p.rankings[metric])+' on the leaderboard':'Unranked','stat-placement'));$('#stats').append(stat)}
 $('#updated').textContent=p.stats?'Synced '+new Date(p.stats.updated_at*1000).toLocaleString('en')+' Â· Titles follow the selection in NovaClient.':'No stats synced yet. Play with the latest NovaClient to start recording.';
 $('#maps').replaceChildren();const highest=Math.max(1,...p.maps.map(m=>m.tries));p.maps.forEach((m,i)=>{const li=text('li','','map-row');li.style.setProperty('--map-fill',`${m.tries/highest*100}%`);li.append(text('span',String(i+1).padStart(2,'0')),text('strong',m.map),text('em',number(m.tries)+' tries'));$('#maps').append(li)});if(!p.maps.length)$('#maps').append(text('li','No map attempts synced yet.','hint'));
}
async function load(){const ticket=++loading;message('');for(const id of ['#login','#verify','#link','#profile'])show(id,false);try{
 if(publicId){const d=await api('/player?id='+encodeURIComponent(publicId));if(ticket===loading)profile(d.profile,false);return}
 const state=await api('/state');if(ticket!==loading)return;csrf=state.csrf;document.dispatchEvent(new CustomEvent('nova-account-state',{detail:state}));if(state.profile&&!state.verified)profile(state.profile,true);else{show('#intro');show(state.verified?'#link':'#verify')}
 }catch(e){if(ticket!==loading)return;if(e.status===401&&!publicId){show('#intro');show('#login')}else{show('#intro',false);message(e.message)}}}
for(const [id,path]of [['#verify-form','/verify'],['#link-form','/link']])$(id).addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;message('');try{await api(path,Object.fromEntries(new FormData(e.target)));e.target.reset();await load()}catch(error){message(error.message)}finally{button.disabled=false}});
$('#reverify').onclick=()=>{show('#profile',false);show('#verify');$('#code').focus()};
async function ranking(){message('');const metric=$('#metric').value,list=$('#ranking-list');list.setAttribute('aria-busy','true');list.replaceChildren(text('li','Loading playersâ€¦','hint'));try{
 const d=await api('/ranking?metric='+encodeURIComponent(metric));if($('#metric').value!==metric)return;list.replaceChildren();d.players.forEach((p,i)=>{
 const li=text('li','','rank-row'),link=text('a','','rank-link');link.href='/account/?player='+encodeURIComponent(p.id);link.setAttribute('aria-label',`Open ${p.name}'s profile`);
 const rank=text('span',String(i+1).padStart(2,'0'),'rank'),badge=text('span','','rank-avatar');badge.append(icon(paths.lasts));
 const identity=text('div','','rank-identity'),name=text('strong',p.name),role=text('span',p.role,'rank-role'),top=text('div','','rank-name');top.append(name,role);identity.append(top);const title=text('p','','player-title');NovaTitles.attach(title,p.title);identity.append(title);
 const value=text('div','','rank-value');value.append(text('strong',format(p.value,d.metric)),text('small',labels[d.metric]));const arrow=icon('M5 12h14m-6-6 6 6-6 6');arrow.classList.add('rank-arrow');link.append(rank,badge,identity,value,arrow);li.append(link);list.append(li)});show('#ranking-empty',!d.players.length);
 const hint=$('#ranking-detail>.hint');if(hint)hint.textContent='Client-recorded totals. Select any player to explore their profile. These are not official KoG rankings.';
 }catch(e){list.replaceChildren();message(e.message)}finally{list.removeAttribute('aria-busy')}}
async function overview(){message('');const grid=$('#category-grid');grid.setAttribute('aria-busy','true');grid.replaceChildren(text('p','Loading categories…','hint'));try{const d=await api('/ranking/overview');if(new URLSearchParams(location.search).has('metric'))return;grid.replaceChildren();for(const category of d.categories){const metric=category.metric;if(!Object.hasOwn(labels,metric))continue;const card=text('article','','category-card'),open=text('a','','category-open');open.href='/leaderboards/?metric='+metric;open.setAttribute('aria-label','View '+labels[metric]+' leaderboard');const glyph=text('span','','category-glyph');glyph.append(icon(paths[metric]));open.append(glyph,text('span',labels[metric],'category-label'),text('span','↗','category-arrow'));card.append(open);const leader=category.leader;if(leader){const line=text('div','','category-leader'),identity=text('div','','category-leader-identity'),name=text('a',leader.name,'category-player');name.href='/account/?player='+encodeURIComponent(leader.id);identity.append(text('small','TOP PLAYER'),name);const title=text('p','','player-title');NovaTitles.attach(title,leader.title);identity.append(title);line.append(identity,text('strong',format(leader.value,metric),'category-value'));card.append(line)}else card.append(text('p','No recorded activity yet.','category-empty'));grid.append(card)}}catch(e){grid.replaceChildren();message(e.message)}finally{grid.removeAttribute('aria-busy')}}
function leaderboardView(){const metric=new URLSearchParams(location.search).get('metric'),detail=Object.hasOwn(labels,metric);show('#ranking-overview',!detail);show('#ranking-detail',detail);if(detail){$('#metric').value=metric;ranking()}else overview()}
$('#metric').onchange=()=>{location.href='/leaderboards/?metric='+encodeURIComponent($('#metric').value)};
async function boot(){const code=new URLSearchParams(location.hash.slice(1)).get('login');if(code){history.replaceState(null,'',location.pathname+location.search);try{const result=await api('/exchange',{code});localStorage.setItem('nova-session',result.token);sessionStorage.removeItem('nova-session');document.dispatchEvent(new CustomEvent('nova-session-changed'))}catch(e){show('#login');message(e.message);return}}
 if(rankings){show('#intro',false);show('#rankings');leaderboardView()}else load()}
boot();document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(rankings)leaderboardView();else load()}});
setInterval(async()=>{if(document.hidden||!profileId||$('#profile').hidden)return;try{const d=await api('/player?id='+encodeURIComponent(profileId));if(JSON.stringify(d.profile.title)!==JSON.stringify(currentTitle)){currentTitle=d.profile.title;NovaTitles.attach($('#title'),currentTitle)}}catch{}},60000);
})();
